            if color == 4:
                continue
            # Find solid rectangular frames by their top-left corner.
            if r == 0 or c == 0 or grid[r-1][c] == color or grid[r][c-1] == color:
                continue
            # A top-left frame corner has same-color right and down neighbors.
            if c+1 >= w or r+1 >= h or grid[r][c+1] != color or grid[r+1][c] != color:
                continue
            # Determine the frame's maximal bounding box from contiguous boundary runs.
            right = c
            while right+1 < w and grid[r][right+1] == color:
                right += 1
            bottom = r
            while bottom+1 < h and grid[bottom+1][c] == color:
                bottom += 1
            # Fill only if the opposite edges close into a rectangle.
            if right <= c+1 or bottom <= r+1:
                continue
            if any(grid[bottom][x] != color for x in range(c, right+1)):
                continue
            if any(grid[y][right] != color for y in range(r, bottom+1)):
                continue
            fill = 2 if color == 3 else 7
            for y in range(r+1, bottom):
                for x in range(c+1, right):
                    out[y][x] = fill
    return out

